s=s.replace('let fields=native_db.sqlite_reply_info(fetched);','').replace('fields["ok"]=="1" && fields["rows"]=="1" && fields["eof"]=="1"','native_db.sqlite_reply_ok(fetched) && native_db.sqlite_reply_count(fetched)==1 && native_db.sqlite_reply_eof(fetched)')
