 r=subprocess.run([str(root/'okkama-rs/target/release/okkama'),'run','--engine','sparrow',str(p)],env=env,text=True,capture_output=True,timeout=120)
 if r.returncode:raise RuntimeError(r.stdout+r.stderr)
 phases={}
 for line in r.stdout.splitlines():
  name,ns,total=line.split();assert int(total)==(500 if name in ['sync','async'] else 3500);phases[name]=int(ns)/1e6
 result['samples'].append(phases);print(i,phases,flush=True)
